// Defines the UTC reporting window. Single source of truth for every project.
// For a backfill, temporarily raise LOOKBACK_DAYS (e.g. 7) and run manually.
const LOOKBACK_DAYS = 1;

const now = new Date();
const end = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate()));
const start = new Date(end.getTime() - LOOKBACK_DAYS * 86400000);
const iso = (d) => d.toISOString().slice(0, 19) + 'Z';

return [{
  json: {
    window_start: iso(start),
    window_end: iso(end),
    report_date: iso(start).slice(0, 10),
    lookback_days: LOOKBACK_DAYS,
    run_at: iso(now)
  }
}];

// Flattens every page of the Zendesk search export into one item per ticket,
// de-duplicates, and re-filters on exact UTC bounds (Zendesk search date
// handling can be timezone-sensitive, so we never trust it alone).
const cfg = $('P1 · Config').first().json;
const start = new Date(cfg.window_start).getTime();
const end = new Date(cfg.window_end).getTime();

const out = [];
const seen = new Set();
let sawResults = false;
let sawError = false;

for (const item of $input.all()) {
  const body = item.json || {};
  if (body.error || body.__error) sawError = true;
  if (Object.prototype.hasOwnProperty.call(body, 'results')) sawResults = true;
  const results = body.results || [];
  for (const t of results) {
    if (!t || !t.id) continue;
    const created = new Date(t.created_at).getTime();
    if (!(created >= start && created < end)) continue;
    if (seen.has(t.id)) continue;
    seen.add(t.id);
    out.push({ json: t });
  }
}

// Never return zero items: an empty branch would be skipped by n8n and the
// project would silently vanish from the report.
// Distinguish "quiet day" from "Zendesk call failed" - reporting fake zeros
// for a failed fetch would be worse than saying nothing.
if (!out.length) return [{ json: { __no_tickets: true, fetch_failed: (sawError || !sawResults) } }];
return out;

// Chunks ticket IDs into batches of 100 for /tickets/show_many.
// ids=0 is a deliberate no-op: Zendesk returns 200 with an empty array,
// which keeps the branch alive on a zero-ticket day.
const tickets = $('P1 · Flatten Tickets').all().map(i => i.json).filter(t => t && t.id);
const ids = tickets.map(t => t.id);
const SIZE = 100;

if (!ids.length) return [{ json: { chunk: 0, ids: '0', empty: true } }];

const out = [];
for (let i = 0; i < ids.length; i += SIZE) {
  out.push({ json: { chunk: i / SIZE, ids: ids.slice(i, i + SIZE).join(','), empty: false } });
}
return out;

// ===========================================================================
//  Joins tickets + metric sets + users, then computes every number in the
//  report. All counting happens here, in code. The LLM never counts anything.
// ===========================================================================
const cfg  = $('P1 · Config').first().json;
const TEXT_LIMIT       = 240;   // chars of opening message sent to Gemini
const MAX_PER_BUCKET   = 2000;  // hard payload guard
const QUOTE_CHARS      = Number(cfg.quote_chars) || 300;   // displayed quote length
const MAX_QUOTES       = Number(cfg.max_quotes) || 10;     // examples per category
const TECH_PER_CLUSTER = Number(cfg.tech_quotes_per_cluster) || 10;
const TECH_QUOTES_MAX  = Number(cfg.tech_quotes_max) || 30;

// ---- 1. Merge sources ------------------------------------------------------
const base = {};
for (const it of $('P1 · Flatten Tickets').all()) {
  const t = it.json;
  if (t && t.id) base[t.id] = t;
}

const metricById = {};
const userById   = {};
for (const it of $('P1 · Fetch Metrics + Users').all()) {
  const b = (it && it.json) || {};
  for (const t of (b.tickets || []))     if (t && t.id && base[t.id]) base[t.id] = Object.assign({}, base[t.id], t);
  for (const m of (b.metric_sets || [])) if (m && m.ticket_id) metricById[m.ticket_id] = m;
  for (const u of (b.users || []))       if (u && u.id) userById[u.id] = u;
}

const tickets = Object.values(base).filter(t => t && t.id);
const fetchFailed = $('P1 · Flatten Tickets').all().some(i => i && i.json && i.json.fetch_failed === true);

// ---- 2. Category taxonomy --------------------------------------------------
// Slug normalisation absorbs per-instance quirks (double vs triple
// underscores, slashes, trailing punctuation) so one map serves all projects.
const norm = (s) => String(s == null ? '' : s)
  .toLowerCase().trim()
  .replace(/[^a-z0-9]+/g, '_')
  .replace(/_+/g, '_')
  .replace(/^_|_$/g, '');

const BUCKETS = [
  { key: 'refunds',       emoji: '\ud83d\udcb0', label: 'Refunds' },
  { key: 'cancellations', emoji: '\ud83d\udeab', label: 'Cancellations' },
  { key: 'billing',       emoji: '\ud83d\udcb3', label: 'Billing & Payments' },
  { key: 'chargeback',    emoji: '\u2696\ufe0f', label: 'Chargebacks & Fraud' },
  { key: 'unidentified',  emoji: '\ud83d\udce7', label: 'Unidentified Contact' },
  { key: 'technical',     emoji: '\ud83d\udee0', label: 'Technical Issues' },
  { key: 'product',       emoji: '\ud83e\udded', label: 'Product & Pricing' },
  { key: 'feedback',      emoji: '\u2b50', label: 'Feedback & Reviews' },
  { key: 'other',         emoji: '\u2753', label: 'Other' }
];

const CATEGORY_MAP = {
  refund_within_30_days_monthly:            'refunds',
  refund_30_day_policy_last_charge_only:     'refunds',
  refund_30_day_policy_two_last_charges:     'refunds',
  refund_within_30_days_trial:               'refunds',
  refund_upsell:                             'refunds',
  refund_paypal2025:                         'refunds',
  refund_rejection:                          'refunds',
  refund_rejection_complaint:                'refunds',
  cancellation_subscription:                 'cancellations',
  cancellation_account_removal:              'cancellations',
  billing:                                   'billing',
  bug_billing:                               'billing',
  disputed_user:                             'chargeback',
  fraudulent_user:                           'chargeback',
  password_and_account_info:                 'unidentified',
  bug_technical_issue:                       'technical',
  service_down:                              'technical',
  results_not_received:                      'technical',
  product_info:                              'product',
  pricing:                                   'product',
  subscription:                              'product',
  feature_request:                            'feedback',
  trustpilot_review:                         'feedback',
  other:                                     'other',
  different_platform_website:                'other',
  special_offers_discounts:                  'other',
  spam:                                      '__noise',
  duplicate_contact:                         '__noise'
};

// Per-project overrides, e.g. {"weird_slug":"refunds"}
let overrides = {};
try { overrides = cfg.category_override_map ? JSON.parse(cfg.category_override_map) : {}; } catch (e) { overrides = {}; }

const bucketFor = (slug) => {
  const n = norm(slug);
  if (!n) return '__uncategorised';
  if (overrides[n]) return overrides[n];
  if (CATEGORY_MAP[n]) return CATEGORY_MAP[n];
  // Prefix fallbacks so brand-new options land somewhere sane.
  if (n.startsWith('refund')) return 'refunds';
  if (n.startsWith('cancellation')) return 'cancellations';
  if (n.startsWith('bug')) return 'technical';
  return '__unmapped';
};

const categoryOf = (t) => {
  const fid = Number(cfg.category_field_id);
  const f = (t.custom_fields || []).find(x => Number(x.id) === fid);
  return f && f.value != null && f.value !== '' ? String(f.value) : '';
};

// ---- 3. Automation classification -----------------------------------------
const johnId  = Number(cfg.automation_agent_id) || 0;
const autoTag = String(cfg.automation_tag || '').trim();
const automationEnabled = johnId > 0;

const isSolved   = (t) => t.status === 'solved' || t.status === 'closed';
const johnSolved = (t) => automationEnabled && Number(t.assignee_id) === johnId;
const johnTouched = (t) => (autoTag && Array.isArray(t.tags) && t.tags.includes(autoTag)) || johnSolved(t);

const classOf = (t) => {
  if (!automationEnabled) return 'manual';
  if (johnSolved(t)) return 'auto';
  if (autoTag && Array.isArray(t.tags) && t.tags.includes(autoTag)) return 'assisted';
  return 'manual';
};

// ---- 4. Stats helpers ------------------------------------------------------
const cal = (v) => (v && typeof v === 'object' && v.calendar != null) ? Number(v.calendar) : null;
const avg = (a) => a.length ? a.reduce((x, y) => x + y, 0) / a.length : null;
const med = (a) => {
  if (!a.length) return null;
  const s = a.slice().sort((x, y) => x - y);
  const m = Math.floor(s.length / 2);
  return s.length % 2 ? s[m] : (s[m - 1] + s[m]) / 2;
};

// ---- 5. Volume -------------------------------------------------------------
const received = tickets.length;
const solved   = tickets.filter(isSolved);
const wasReopened = (t) => {
  const m = metricById[t.id];
  return !!(m && Number(m.reopens) > 0);
};
const reopenedTickets = tickets.filter(wasReopened);
const reopened = reopenedTickets.length;
const refunds = tickets.filter(t => norm(categoryOf(t)).startsWith('refund')).length;

// ---- 6. Automation split ---------------------------------------------------
const solvedByClass = { auto: [], assisted: [], manual: [] };
for (const t of solved) solvedByClass[classOf(t)].push(t);
const touched = tickets.filter(johnTouched).length;

// A ticket that was solved and then reopened is currently 'open', so it is NOT
// in `solved`. Reopen rate therefore needs its own denominator: everything that
// reached solved at least once.
const everSolvedByClass = { auto: [], assisted: [], manual: [] };
for (const t of tickets) {
  if (isSolved(t) || wasReopened(t)) everSolvedByClass[classOf(t)].push(t);
}
const reopenSplit = { auto: 0, assisted: 0, manual: 0 };
for (const t of reopenedTickets) reopenSplit[classOf(t)]++;

// ---- 7. Performance (solved tickets only, three columns) -------------------
const perf = {};
for (const k of ['auto', 'assisted', 'manual']) {
  const set = solvedByClass[k];
  const frt = [], res = [], rep = [];
  let oneTouch = 0, repCount = 0;
  for (const t of set) {
    const m = metricById[t.id] || {};
    const a = cal(m.reply_time_in_minutes);
    const b = cal(m.full_resolution_time_in_minutes);
    if (a != null) frt.push(a);
    if (b != null) res.push(b);
    if (m.replies != null) { rep.push(Number(m.replies)); repCount++; if (Number(m.replies) === 1) oneTouch++; }
  }
  const ever = everSolvedByClass[k];
  const reo = ever.filter(wasReopened).length;
  perf[k] = {
    n: set.length,
    ever_solved: ever.length,
    reopened: reo,
    reopen_pct: ever.length ? (reo / ever.length) * 100 : null,
    frt_avg: avg(frt), frt_med: med(frt),
    res_avg: avg(res), res_med: med(res),
    rep_avg: avg(rep),
    one_touch_pct: repCount ? (oneTouch / repCount) * 100 : null
  };
}

// ---- 8. Solved by agent ----------------------------------------------------
const agentCounts = {};
for (const t of solved) {
  let name;
  if (t.assignee_id == null) name = 'Unassigned';
  else if (automationEnabled && Number(t.assignee_id) === johnId) name = cfg.automation_agent_name || 'Automation';
  else name = (userById[t.assignee_id] && userById[t.assignee_id].name) || ('User ' + t.assignee_id);
  agentCounts[name] = (agentCounts[name] || 0) + 1;
}
const autoName = cfg.automation_agent_name || 'Automation';
const agents = Object.keys(agentCounts)
  .map(name => ({ name, count: agentCounts[name] }))
  .sort((a, b) => {
    if (a.name === autoName) return -1;
    if (b.name === autoName) return 1;
    if (a.name === 'Unassigned') return 1;
    if (b.name === 'Unassigned') return -1;
    return b.count - a.count;
  });

// ---- 9. Request breakdown --------------------------------------------------
const grouped = {};
BUCKETS.forEach(b => { grouped[b.key] = []; });
const noiseDetail = {};
const unmappedDetail = {};
let noiseTotal = 0, uncategorised = 0, unmappedTotal = 0;

for (const t of tickets) {
  const raw = categoryOf(t);
  const b = bucketFor(raw);
  if (b === '__noise') {
    noiseTotal++;
    const n = norm(raw);
    noiseDetail[n] = (noiseDetail[n] || 0) + 1;
  } else if (b === '__uncategorised') {
    uncategorised++;
  } else if (b === '__unmapped') {
    unmappedTotal++;
    unmappedDetail[raw] = (unmappedDetail[raw] || 0) + 1;
  } else {
    grouped[b].push(t);
  }
}

const denom = BUCKETS.reduce((s, b) => s + grouped[b.key].length, 0);
const uniqueCustomers = new Set(
  BUCKETS.flatMap(b => grouped[b.key]).map(t => t.requester_id).filter(x => x != null)
).size;

// Per-type refund breakdown. Labels are derived from the slug rather than
// hardcoded, so a new refund option appears automatically on every project.
const refundSet = grouped.refunds;
const refundCounts = {};
for (const t of refundSet) {
  const n = norm(categoryOf(t)) || 'unspecified';
  refundCounts[n] = (refundCounts[n] || 0) + 1;
}
const refundTypes = Object.keys(refundCounts).map(slug => ({
  slug,
  label: slug.replace(/^refund_/, '').replace(/_/g, ' ').trim() || 'unspecified',
  count: refundCounts[slug]
})).sort((a, b) => b.count - a.count);

const breakdown = BUCKETS.map(b => ({
  key: b.key,
  emoji: b.emoji,
  label: b.label,
  count: grouped[b.key].length,
  pct: denom ? (grouped[b.key].length / denom) * 100 : 0
}));

// ---- 10. Text payloads for Gemini -----------------------------------------
// Ticket id + subject + truncated opening message only.
// No customer names, no email addresses, no full threads leave the stack.
const clean = (s) => String(s == null ? '' : s).replace(/\s+/g, ' ').trim().slice(0, TEXT_LIMIT);

// Collapse a ticket body to a single quotable line: drop quoted reply chains
// and anything after a signature delimiter, then squash whitespace.
const quoteOf = (t) => {
  const lines = String(t.description == null ? '' : t.description).split(/\r?\n/);
  const keep = [];
  for (const ln of lines) {
    if (/^\s*--\s*$/.test(ln)) break;                       // signature delimiter
    if (/^\s*>/.test(ln)) continue;                          // quoted reply
    if (/^\s*On .{0,90}\bwrote:\s*$/i.test(ln)) continue;    // reply header
    keep.push(ln);
  }
  let s = keep.join(' ').replace(/\s+/g, ' ').trim();
  if (s.length > QUOTE_CHARS) s = s.slice(0, QUOTE_CHARS - 1).replace(/\s+\S*$/, '') + '\u2026';
  return s;
};

const zdBase = String(cfg.zendesk_base || '').replace(/\/+$/, '');
const emailOf = (t) => {
  const u = userById[t.requester_id];
  return (u && u.email) ? u.email : ('user ' + t.requester_id);
};

const entry = (t) => ({
  id: String(t.id),
  subject: clean(t.subject),
  text: clean(t.description),          // what the model sees
  quote: quoteOf(t),                   // what Slack shows
  email: emailOf(t),
  url: zdBase + '/agent/tickets/' + t.id
});

const bucketTickets = {};
for (const b of BUCKETS) {
  if (!grouped[b.key].length) continue;
  bucketTickets[b.key] = grouped[b.key].slice(0, MAX_PER_BUCKET).map(entry);
}

return [{
  json: {
    project_key: cfg.project_key,
    project_display_name: cfg.project_display_name,
    gemini_model: cfg.gemini_model,
    report_date: cfg.report_date,
    window_start: cfg.window_start,
    window_end: cfg.window_end,
    fetch_failed: fetchFailed,
    automation_enabled: automationEnabled,
    automation_agent_name: autoName,
    automation_tag: autoTag,
    volume: {
      received,
      solved: solved.length,
      still_open: received - solved.length,
      reopened,
      reopen_split: reopenSplit,
      refunds,
      resolution_rate: received ? (solved.length / received) * 100 : 0
    },
    automation: {
      auto: solvedByClass.auto.length,
      assisted: solvedByClass.assisted.length,
      manual: solvedByClass.manual.length,
      touch_rate: received ? (touched / received) * 100 : 0
    },
    performance: perf,
    agents,
    breakdown: {
      denom,
      unique_customers: uniqueCustomers,
      noise_total: noiseTotal,
      noise_detail: noiseDetail,
      uncategorised,
      unmapped_total: unmappedTotal,
      unmapped_detail: unmappedDetail,
      buckets: breakdown,
      refund_types: refundTypes
    },
    max_quotes: MAX_QUOTES,
    tech_quotes_per_cluster: TECH_PER_CLUSTER,
    tech_quotes_max: TECH_QUOTES_MAX,
    quote_chars: QUOTE_CHARS,
    run_at: cfg.run_at,
    bucket_tickets: bucketTickets,
    tech_tickets: bucketTickets.technical || []
  }
}];

