const touched = tickets.filter(johnTouched).length;

// A ticket that was solved and then reopened is currently 'open', so it is NOT
// in `solved`. Reopen rate therefore needs its own denominator: everything that
// reached solved at least once.
const everSolvedByClass = { auto: [], assisted: [], manual: [] };
for (const t of tickets) {
  if (isSolved(t) || wasReopened(t)) everSolvedByClass[classOf(t)].push(t);
}
const reopenSplit = { auto: 0, assisted: 0, manual: 0 };
for (const t of reopenedTickets) reopenSplit[classOf(t)]++;

// ---- 7. Performance (solved tickets only, three columns) -------------------
