const clean = (s) => String(s == null ? '' : s).replace(/\s+/g, ' ').trim().slice(0, TEXT_LIMIT);

// Collapse a ticket body to a single quotable line: drop quoted reply chains
// and anything after a signature delimiter, then squash whitespace.
const quoteOf = (t) => {
  const lines = String(t.description == null ? '' : t.description).split(/\r?\n/);
  const keep = [];
  for (const ln of lines) {
    if (/^\s*--\s*$/.test(ln)) break;                       // signature delimiter
    if (/^\s*>/.test(ln)) continue;                          // quoted reply
    if (/^\s*On .{0,90}\bwrote:\s*$/i.test(ln)) continue;    // reply header
    keep.push(ln);
  }
  let s = keep.join(' ').replace(/\s+/g, ' ').trim();
  if (s.length > QUOTE_CHARS) s = s.slice(0, QUOTE_CHARS - 1).replace(/\s+\S*$/, '') + '\u2026';
  return s;
};

