  const t = it.json;
  if (t && t.id) base[t.id] = t;
}

const metricById = {};
const userById   = {};
for (const it of $('P7 · Fetch Metrics + Users').all()) {
  const b = (it && it.json) || {};
  for (const t of (b.tickets || []))     if (t && t.id && base[t.id]) base[t.id] = Object.assign({}, base[t.id], t);
  for (const m of (b.metric_sets || [])) if (m && m.ticket_id) metricById[m.ticket_id] = m;
  for (const u of (b.users || []))       if (u && u.id) userById[u.id] = u;
}

const tickets = Object.values(base).filter(t => t && t.id);
