  { key: 'refunds',       emoji: '\ud83d\udcb0', label: 'Refunds' },
  { key: 'cancellations', emoji: '\ud83d\udeab', label: 'Cancellations' },
  { key: 'billing',       emoji: '\ud83d\udcb3', label: 'Billing & Payments' },
