const quoteOf = (t) => {
  const lines = String(t.description == null ? '' : t.description).split(/\r?\n/);
  const keep = [];
  for (const ln of lines) {
    if (/^\s*--\s*$/.test(ln)) break;                       // signature delimiter
    if (/^\s*>/.test(ln)) continue;                          // quoted reply
    if (/^\s*On .{0,90}\bwrote:\s*$/i.test(ln)) continue;    // reply header
    keep.push(ln);
  }
