  json: {
    project_key: cfg.project_key,
    project_display_name: cfg.project_display_name,
    gemini_model: cfg.gemini_model,
    report_date: cfg.report_date,
    window_start: cfg.window_start,
    window_end: cfg.window_end,
    fetch_failed: fetchFailed,
    automation_enabled: automationEnabled,
    automation_agent_name: autoName,
    automation_tag: autoTag,
    volume: {
      received,
      solved: solved.length,
      still_open: received - solved.length,
      reopened,
      reopen_split: reopenSplit,
      refunds,
      resolution_rate: received ? (solved.length / received) * 100 : 0
    },
    automation: {
      auto: solvedByClass.auto.length,
      assisted: solvedByClass.assisted.length,
      manual: solvedByClass.manual.length,
      touch_rate: received ? (touched / received) * 100 : 0
    },
    performance: perf,
    agents,
    breakdown: {
      denom,
      unique_customers: uniqueCustomers,
      noise_total: noiseTotal,
      noise_detail: noiseDetail,
      uncategorised,
      unmapped_total: unmappedTotal,
      unmapped_detail: unmappedDetail,
      buckets: breakdown,
      refund_types: refundTypes
    },
    max_quotes: MAX_QUOTES,
    tech_quotes_per_cluster: TECH_PER_CLUSTER,
    tech_quotes_max: TECH_QUOTES_MAX,
    quote_chars: QUOTE_CHARS,
    run_at: cfg.run_at,
    bucket_tickets: bucketTickets,
    tech_tickets: bucketTickets.technical || []
  }
}];

