        generationConfig: {
          temperature: 0.2,
          thinkingConfig: { thinkingLevel: 'low' },
          maxOutputTokens: 2048,
          responseMimeType: 'application/json',
          responseSchema: SCHEMA
        }
      }
    })
  };
});

// Pass 2 of 2: assign each technical ticket to one of the discovered labels.
// Chunked at 80 tickets per call to keep every response short and complete.
const projects = $('Prepare Tech Discovery').all().map(i => i.json);
const resp = $input.all();
const CHUNK = 80;

const NOOP_BODY = {
  contents: [{ role: 'user', parts: [{ text: 'Return the JSON object {"ok":true}.' }] }],
  generationConfig: {
    temperature: 0,
    maxOutputTokens: 64,
    responseMimeType: 'application/json',
    responseSchema: { type: 'OBJECT', properties: { ok: { type: 'BOOLEAN' } }, required: ['ok'] }
  }
};

const readJson = (item) => {
  try {
    const parts = item.json.candidates[0].content.parts || [];
    const txt = parts.map(p => p.text || '').join('').replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
    return JSON.parse(txt);
  } catch (e) { return null; }
};

const SYSTEM = [
  'You assign technical support tickets to issue types.',
  'You receive a fixed list of labels and a list of tickets, each with an id.',
  'Assign every ticket to exactly one label from the list.',
  'If a ticket genuinely fits none of the labels, use the exact string Other.',
  'Return one entry per input ticket, reusing the ids exactly as given.',
  'Return JSON only, in the form {"assignments":[{"id":"123","label":"..."}]}.'
].join(' ');

const SCHEMA = {
  type: 'OBJECT',
  properties: {
    assignments: {
      type: 'ARRAY',
      items: {
        type: 'OBJECT',
        properties: { id: { type: 'STRING' }, label: { type: 'STRING' } },
        required: ['id', 'label']
      }
    }
  },
  required: ['assignments']
};

const out = [];

for (let i = 0; i < projects.length; i++) {
  const p = projects[i];
  const parsed = resp[i] ? readJson(resp[i]) : null;
  let labels = (parsed && Array.isArray(parsed.labels) ? parsed.labels : [])
    .map(x => String(x || '').trim()).filter(Boolean).slice(0, 8);
  const tix = p.tech_tickets || [];

  if (!tix.length || !labels.length) {
    out.push({ json: { project_key: p.project_key, job: 'noop', labels, model: p.gemini_model, request_body: NOOP_BODY } });
    continue;
  }

  for (let j = 0; j < tix.length; j += CHUNK) {
    const slice = tix.slice(j, j + CHUNK);
    const lines = slice.map(t => t.id + ' | ' + (t.subject || '(no subject)') + ' :: ' + (t.text || '')).join('\n');
    out.push({
      json: {
        project_key: p.project_key,
        job: 'classify',
        labels,
        model: p.gemini_model,
        request_body: {
          systemInstruction: { parts: [{ text: SYSTEM }] },
          contents: [{ role: 'user', parts: [{ text: 'Labels:\n' + labels.map(l => '- ' + l).join('\n') + '\n\nTickets:\n' + lines }] }],
          generationConfig: {
            temperature: 0,
            thinkingConfig: { thinkingLevel: 'low' },
            maxOutputTokens: 16384,
            responseMimeType: 'application/json',
            responseSchema: SCHEMA
          }
        }
      }
    });
  }
}

return out;

// Counting happens here, never in the model. Any ticket the model failed to
// classify falls into Other, so the total always reconciles.
const projects = $('Prepare Tech Discovery').all().map(i => i.json);
const jobs = $('Prepare Tech Classify').all().map(i => i.json);
const resp = $input.all();

const readJson = (item) => {
  try {
    const parts = item.json.candidates[0].content.parts || [];
    const txt = parts.map(p => p.text || '').join('').replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
    return JSON.parse(txt);
  } catch (e) { return null; }
};

const assignedByProject = {};
const labelsByProject = {};

for (let i = 0; i < jobs.length; i++) {
  const job = jobs[i];
  if (!job) continue;
  labelsByProject[job.project_key] = job.labels || [];
  if (job.job !== 'classify') continue;

  const valid = new Set(job.labels || []);
  const parsed = resp[i] ? readJson(resp[i]) : null;
  const arr = (parsed && Array.isArray(parsed.assignments)) ? parsed.assignments : [];

  assignedByProject[job.project_key] = assignedByProject[job.project_key] || {};
  const store = assignedByProject[job.project_key];
  for (const a of arr) {
    const id = String((a && a.id) != null ? a.id : '').trim();
    if (!id || store[id]) continue;
    store[id] = valid.has(a.label) ? a.label : 'Other';
  }
}

return projects.map(p => {
  const tix = p.tech_tickets || [];
  const store = assignedByProject[p.project_key] || {};
  const counts = {};
  for (const t of tix) {
    const lab = store[String(t.id)] || 'Other';
    counts[lab] = (counts[lab] || 0) + 1;
  }
  const items = Object.keys(counts)
    .map(label => ({ label, count: counts[label] }))
    .sort((a, b) => (a.label === 'Other' ? 1 : b.label === 'Other' ? -1 : b.count - a.count));

  // Needed so the report can group the selected example tickets by cluster.
  const assignments = {};
  for (const t of tix) assignments[String(t.id)] = store[String(t.id)] || 'Other';

  return { json: Object.assign({}, p, { tech: { total: tix.length, items, assignments, labels: labelsByProject[p.project_key] || [] } }) };
});

// Scores tickets for how much actionable feedback they carry. Scoring is
// strictly WITHIN one category group - refund tickets are never compared
// against technical ones. Groups at or under the quote limit skip the call
// entirely and every ticket is shown.
const projects = $input.all().map(i => i.json);
const CHUNK = 100;

const NOOP_BODY = {
  contents: [{ role: 'user', parts: [{ text: 'Return the JSON object {"ok":true}.' }] }],
  generationConfig: {
    temperature: 0,
    maxOutputTokens: 64,
    responseMimeType: 'application/json',
    responseSchema: { type: 'OBJECT', properties: { ok: { type: 'BOOLEAN' } }, required: ['ok'] }
  }
};

const SYSTEM = (n) => [
  'You triage customer support tickets to surface the ones that give a product and operations team the most actionable feedback.',
  'You receive tickets from a single category group, each with an id, a subject and the opening message.',
  'Return up to ' + n + ' tickets, each scored 1 to 5 on this absolute scale:',
  '5 - names a specific concrete failure, friction point or unmet expectation, with enough detail to act on;',
  '4 - a clear complaint about one identifiable aspect of the product, billing or service, with some detail;',
  '3 - a real underlying issue is visible but described vaguely;',
  '2 - generic dissatisfaction or a bare request with no specifics;',
  '1 - no informational content at all.',
  'Score against the scale itself, not relative to the other tickets in this batch - two batches of the same quality must receive the same scores.',
  'Favour variety: when many tickets describe the same problem, score only the one or two clearest highly and spend the remaining slots on different problems.',
  'Favour concrete detail over emotional intensity. A calm ticket naming exactly what broke is more useful than an angry one that names nothing.',
  'Only use ids that appear in the input. Return JSON only.'
].join(' ');

const SCHEMA = {
  type: 'OBJECT',
  properties: {
    picks: {
      type: 'ARRAY',
      items: {
        type: 'OBJECT',
        properties: { id: { type: 'STRING' }, score: { type: 'INTEGER' } },
        required: ['id', 'score']
      }
    }
  },
  required: ['picks']
};

const out = [];

for (const p of projects) {
  const max = Number(p.max_quotes) || 10;
  const techPer = Number(p.tech_quotes_per_cluster) || 10;

  for (const b of (p.breakdown.buckets || [])) {
    const tix = (p.bucket_tickets || {})[b.key] || [];
    if (tix.length <= max) continue;   // shown in full, nothing to rank

    // Technical is allocated per cluster, so it needs more scored candidates
    // than a flat top-N would - enough to fill several clusters.
    const wantPicks = (b.key === 'technical')
      ? Math.min(30, Math.max(max, techPer * 3))
      : max;

    for (let i = 0; i < tix.length; i += CHUNK) {
      const slice = tix.slice(i, i + CHUNK);
      const lines = slice.map(t => t.id + ' | ' + (t.subject || '(no subject)') + ' :: ' + (t.text || '')).join('\n');
      out.push({
        json: {
          project_key: p.project_key,
          bucket_key: b.key,
          job: 'select',
          model: p.gemini_model,
          ids: slice.map(t => t.id),
          want: wantPicks,
          request_body: {
            systemInstruction: { parts: [{ text: SYSTEM(wantPicks) }] },
            contents: [{ role: 'user', parts: [{ text: 'Category group: ' + b.label + '\nReturn up to ' + wantPicks + ' scored tickets.\nTickets (' + slice.length + '):\n' + lines }] }],
            generationConfig: {
              temperature: 0.1,
              thinkingConfig: { thinkingLevel: 'low' },
              maxOutputTokens: 8192,
              responseMimeType: 'application/json',
              responseSchema: SCHEMA
            }
          }
        }
      });
    }
  }
}

if (!out.length) {
  out.push({
    json: {
      project_key: (projects[0] && projects[0].project_key) || 'none',
      bucket_key: null, job: 'noop', ids: [], want: 0,
      model: (projects[0] && projects[0].gemini_model) || 'gemini-3.6-flash',
      request_body: NOOP_BODY
    }
  });
}

return out;

// Pools the model's scores across chunks; the final choice is made here in code.
const projects = $('Count Tech Issues').all().map(i => i.json);
const jobs = $('Prep Quote Selection').all().map(i => i.json);
const resp = $input.all();

const readJson = (item) => {
  try {
    const parts = item.json.candidates[0].content.parts || [];
    const txt = parts.map(p => p.text || '').join('').replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
    return JSON.parse(txt);
  } catch (e) { return null; }
};

// project -> bucket -> { ticket_id: best score }
const scores = {};
for (let i = 0; i < jobs.length; i++) {
  const job = jobs[i];
  if (!job || job.job !== 'select') continue;
  const allowed = new Set((job.ids || []).map(String));
  const parsed = resp[i] ? readJson(resp[i]) : null;
  const picks = (parsed && Array.isArray(parsed.picks)) ? parsed.picks : [];
  scores[job.project_key] = scores[job.project_key] || {};
  const bucket = scores[job.project_key][job.bucket_key] = scores[job.project_key][job.bucket_key] || {};
  for (const pk of picks) {
    const id = String((pk && pk.id) != null ? pk.id : '').trim();
    if (!id || !allowed.has(id)) continue;           // ignore ids not in the input
    const sc = Math.max(1, Math.min(5, Number(pk.score) || 1));
    if (bucket[id] == null || sc > bucket[id]) bucket[id] = sc;
  }
}

return projects.map(p => {
  const max = Number(p.max_quotes) || 10;
  const chosen = {};

  for (const b of (p.breakdown.buckets || [])) {
    const tix = (p.bucket_tickets || {})[b.key] || [];
    if (!tix.length) continue;

    const sc = ((scores[p.project_key] || {})[b.key]) || {};
    const order = new Map(tix.map((t, idx) => [t.id, idx]));
    const byScore = (x, y) => ((sc[y.id] || 0) - (sc[x.id] || 0)) || (order.get(x.id) - order.get(y.id));

    if (tix.length <= max) { chosen[b.key] = tix.slice(); continue; }

    // ---- technical: allocate per discovered cluster ------------------------
    // Every cluster is guaranteed at least one example before the overall cap
    // applies, so no issue type can be starved - including the `Other`
    // fallback, which holds the tickets the taxonomy failed to cover.
    if (b.key === 'technical') {
      const asg = (p.tech && p.tech.assignments) || {};
      const byCluster = {};
      for (const t of tix) {
        const lab = asg[String(t.id)] || 'Other';
        (byCluster[lab] = byCluster[lab] || []).push(t);
      }
      // Biggest clusters first, `Other` last - matches the order they render in.
      const clusterOrder = (p.tech.items || []).map(it => it.label).filter(l => byCluster[l]);
      for (const l of Object.keys(byCluster)) if (clusterOrder.indexOf(l) === -1) clusterOrder.push(l);
      for (const l of clusterOrder) byCluster[l].sort(byScore);

      const perCluster = Number(p.tech_quotes_per_cluster) || 10;
      const totalCap = Number(p.tech_quotes_max) || 30;
      const pickedT = [];
      for (let round = 0; round < perCluster; round++) {
        for (const l of clusterOrder) {
          const arr = byCluster[l];
          if (round >= arr.length) continue;
          if (round > 0 && pickedT.length >= totalCap) continue;   // round 0 is never skipped
          pickedT.push(arr[round]);
        }
      }
      chosen[b.key] = pickedT;
      continue;
    }

    // ---- everything else: flat top-N by score ----------------------------
    const ranked = tix.filter(t => sc[t.id] != null).sort(byScore);
    const picked = ranked.slice(0, max);
    if (picked.length < max) {
      const have = new Set(picked.map(t => t.id));
      for (const t of tix) {
        if (picked.length >= max) break;
        if (!have.has(t.id)) picked.push(t);
      }
    }
    chosen[b.key] = picked;
  }

  return { json: Object.assign({}, p, { quotes: chosen }) };
});

// The metrics tables live in a code block so the columns line up. The breakdown
// sits outside it, because Slack will not render links inside a code block.
const pad  = (s, n) => String(s).padEnd(n);
const padL = (s, n) => String(s).padStart(n);

const dur = (m) => {
  if (m == null || isNaN(m)) return '-';
  const t = Math.round(Number(m));
  if (t < 60) return t + 'm';
  const h = Math.floor(t / 60);
  const mm = t % 60;
  return h + 'h ' + (mm < 10 ? '0' : '') + mm + 'm';
};
const pct = (v) => (v == null || isNaN(v)) ? '-' : (Math.round(Number(v) * 10) / 10).toFixed(1) + '%';
const one = (v) => (v == null || isNaN(v)) ? '-' : (Math.round(Number(v) * 10) / 10).toFixed(1);
const rule = (t) => '\u2501\u2501\u2501 ' + t + ' ' + '\u2501'.repeat(Math.max(3, 46 - t.length));
const head = (t) => '*' + '\u2501'.repeat(6) + ' ' + t + ' ' + '\u2501'.repeat(6) + '*';
const stamp = (iso) => String(iso || '').replace('T', ' ').slice(0, 16) + ' UTC';

// Slack mrkdwn: & < > must be escaped or customer text can break the links.
const esc = (s) => String(s == null ? '' : s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  .replace(/```/g, "'");

const cut = (s, n) => {
  const t = String(s == null ? '' : s);
  return t.length > n ? t.slice(0, n - 1).replace(/\s+\S*$/, '') + '\u2026' : t;
};

// Blank lines inserted between each request-breakdown category and between each
// technical cluster. Change this one number to tighten or loosen the spacing.
const SECTION_GAP = 3;   // blank lines between breakdown categories / clusters
const gap = (L) => { for (let i = 0; i < SECTION_GAP; i++) L.push(''); };

return $input.all().map(item => {
  const p = item.json;
  const v = p.volume, a = p.automation, f = p.performance, bd = p.breakdown;

  if (p.fetch_failed) {
    const F = [];
    F.push('\u26a0\ufe0f *CS Report \u00b7 ' + p.project_display_name + ' \u00b7 ' + p.report_date + '*');
    F.push('Could not retrieve tickets from Zendesk for this window, so no report was produced.');
    F.push('The other projects are unaffected. Check the failed execution in n8n.');
    return { json: Object.assign({}, p, { slack_text: F.join('\n') }) };
  }

  const quoteLine = (q, qlen) =>
    '\u2022 "' + esc(cut(q.quote || '(empty message)', qlen)) + '"  (<' + q.url + '|#' + q.id + '> \u00b7 ' + esc(q.email) + ')';

  // Rendered as a function so the report can be rebuilt with shorter quotes if
  // it would otherwise blow past Slack's 40k character ceiling.
  const build = (qlen) => {
    const L = [];
    L.push('\ud83d\udcca *CS Report \u00b7 ' + p.project_display_name + ' \u00b7 ' + p.report_date + '*');
    L.push('```');
    L.push('Cohort: ' + v.received + ' tickets received ' + p.report_date + ' 00:00-23:59 UTC');
    L.push(p.run_at
      ? 'Status as of ' + stamp(p.run_at) + ' \u00b7 tickets solved later are not counted'
      : 'Status as at report time \u00b7 tickets solved later are not counted');
    L.push('');

    L.push(rule('TRANSITIONED TICKETS'));
    L.push(pad('Received', 26) + padL(v.received, 6));
    L.push(pad('Solved', 26) + padL(v.solved, 6) + '   (' + pct(v.resolution_rate) + ' of received)');
    L.push(pad('Still open', 26) + padL(v.still_open, 6));
    if (p.automation_enabled && v.reopened) {
      const rs = v.reopen_split || {};
      L.push(pad('Reopened at least once', 26) + padL(v.reopened, 6) +
        '   (auto ' + (rs.auto || 0) + ' \u00b7 assisted ' + (rs.assisted || 0) + ' \u00b7 manual ' + (rs.manual || 0) + ')');
    } else {
      L.push(pad('Reopened at least once', 26) + padL(v.reopened, 6));
    }
    L.push(pad('Refund requests', 26) + padL(v.refunds, 6));
    for (const r of (bd.refund_types || [])) {
      L.push(pad('   \u21b3 ' + r.label, 40) + padL(r.count, 5));
    }
    L.push('');

    if (p.automation_enabled) {
      L.push(rule('AUTOMATION'));
      const share = (n) => v.solved ? '   (' + pct((n / v.solved) * 100) + ' of solved)' : '';
      L.push(pad('Fully automated', 26) + padL(a.auto, 6) + share(a.auto));
      L.push(pad('Assisted (bot then human)', 26) + padL(a.assisted, 6) + share(a.assisted));
      L.push(pad('Fully manual', 26) + padL(a.manual, 6) + share(a.manual));
      L.push(pad('Automation touch rate', 26) + padL(pct(a.touch_rate), 6) + '   (of received)');
      if (!p.automation_tag) L.push('! No automation tag configured - assisted tickets count as manual.');
      L.push('');

      L.push(rule('PERFORMANCE (solved)'));
      L.push(pad('', 26) + pad('Auto', 12) + pad('Assisted', 12) + pad('Manual', 12));
      L.push(pad('Solved tickets', 26) + pad(f.auto.n, 12) + pad(f.assisted.n, 12) + pad(f.manual.n, 12));
      L.push(pad('First response   avg', 26) + pad(dur(f.auto.frt_avg), 12) + pad(dur(f.assisted.frt_avg), 12) + pad(dur(f.manual.frt_avg), 12));
      L.push(pad('                 med', 26) + pad(dur(f.auto.frt_med), 12) + pad(dur(f.assisted.frt_med), 12) + pad(dur(f.manual.frt_med), 12));
      L.push(pad('Resolution       avg', 26) + pad(dur(f.auto.res_avg), 12) + pad(dur(f.assisted.res_avg), 12) + pad(dur(f.manual.res_avg), 12));
      L.push(pad('                 med', 26) + pad(dur(f.auto.res_med), 12) + pad(dur(f.assisted.res_med), 12) + pad(dur(f.manual.res_med), 12));
      L.push(pad('Agent replies    avg', 26) + pad(one(f.auto.rep_avg), 12) + pad(one(f.assisted.rep_avg), 12) + pad(one(f.manual.rep_avg), 12));
      L.push(pad('One-touch rate', 26) + pad(pct(f.auto.one_touch_pct), 12) + pad(pct(f.assisted.one_touch_pct), 12) + pad(pct(f.manual.one_touch_pct), 12));
      L.push(pad('Reopen rate', 26) + pad(pct(f.auto.reopen_pct), 12) + pad(pct(f.assisted.reopen_pct), 12) + pad(pct(f.manual.reopen_pct), 12));
    } else {
      L.push(rule('PERFORMANCE (solved)'));
      L.push(pad('First response   avg/med', 26) + dur(f.manual.frt_avg) + ' / ' + dur(f.manual.frt_med));
      L.push(pad('Resolution       avg/med', 26) + dur(f.manual.res_avg) + ' / ' + dur(f.manual.res_med));
      L.push(pad('Agent replies    avg', 26) + one(f.manual.rep_avg));
      L.push(pad('One-touch rate', 26) + pct(f.manual.one_touch_pct));
      L.push(pad('Reopen rate', 26) + pct(f.manual.reopen_pct));
    }
    L.push('');

    L.push(rule('SOLVED BY AGENT'));
    if (!p.agents.length) L.push('  (none)');
    for (const ag of p.agents) L.push(pad('  ' + ag.name, 26) + padL(ag.count, 6));
    L.push('```');

    // ---- breakdown: outside the code block so ticket links are clickable ----
    const nd = Object.keys(bd.noise_detail).map(k => k.replace(/_/g, ' ') + ' ' + bd.noise_detail[k]).join(' \u00b7 ');
    L.push(head('REQUEST BREAKDOWN'));
    L.push('Categorised: ' + bd.denom + '  \u00b7  Unique customers: ' + bd.unique_customers +
           '  \u00b7  Noise excluded: ' + bd.noise_total + (nd ? ' (' + nd + ')' : ''));

    for (const b of bd.buckets) {
      if (!b.count) continue;
      gap(L);
      const h = b.emoji + ' *' + b.label + '* \u2014 ' + b.count + ' (' + pct(b.pct) + ')';
      if (b.key === 'technical') { L.push(h + '  \u2192 examples grouped by issue below'); continue; }
      L.push(h);
      const qs = (p.quotes || {})[b.key] || [];
      if (!qs.length) L.push('   _no examples available_');
      for (const q of qs) L.push(quoteLine(q, qlen));
    }

    if (bd.unmapped_total) {
      const u = Object.keys(bd.unmapped_detail).map(k => k + ' (' + bd.unmapped_detail[k] + ')').join(', ');
      gap(L);
      L.push('\u26a0\ufe0f *Unmapped categories* \u2014 ' + bd.unmapped_total + ': ' + esc(u));
    }
    if (bd.uncategorised) {
      gap(L);
      L.push('\u2754 *No category set* \u2014 ' + bd.uncategorised);
    }

    // ---- technical issues, grouped by discovered cluster ----
    gap(L);
    L.push(head('TECHNICAL ISSUES'));
    L.push('Technical tickets: ' + p.tech.total);
    if (!p.tech.total) {
      L.push('   _none today_');
    } else if (!p.tech.items.length) {
      L.push('   _clustering unavailable_');
    } else {
      const sel = (p.quotes || {})['technical'] || [];
      const asg = (p.tech && p.tech.assignments) || {};
      for (const it of p.tech.items) {
        gap(L);
        L.push('*' + esc(it.label) + '* \u2014 ' + it.count);
        const qs = sel.filter(q => (asg[String(q.id)] || 'Other') === it.label);
        if (!qs.length) L.push('   _no example selected_');
        for (const q of qs) L.push(quoteLine(q, qlen));
      }
    }
    return L.join('\n');
  };

  const baseLen = Number(p.quote_chars) || 300;
  let text = build(baseLen);
  if (text.length > 39000) {
    text = build(Math.max(120, Math.floor(baseLen / 2))) +
      '\n\n_[quotes shortened to fit Slack\u2019s message limit]_';
  }
  if (text.length > 39000) {
    text = text.slice(0, 38800) + '\n\n_[report truncated \u2013 lower max_quotes or tech_quotes_max in the project config]_';
  }
  return { json: Object.assign({}, p, { slack_text: text }) };
});
